@@ -0,0 +1,35 @@
+import type { Migration } from "./types";
+
+const migration051: Migration = {
+  version: 51,
+  name: "matches-unique-item-aware",
+  up(db) {
+    // Expand the uniqueness key to include cargo_item_index + vessel_item_index.
+    // Without this, the second cargo item from a multi-item email shares the same
+    // cargo_id as the first item, collides on the old (cargo_id, vessel_id, user_id)
+    // index, and is silently dropped — only one match per email pair was stored (C.5).
+    db.exec(`
+      DELETE FROM matches
+      WHERE rowid NOT IN (
+        SELECT MIN(rowid) FROM matches
+        GROUP BY cargo_id, vessel_id, COALESCE(user_id, ''),
+                 COALESCE(cargo_item_index, 0), COALESCE(vessel_item_index, 0)
+      )
+    `);
+    db.exec(`DROP INDEX IF EXISTS idx_matches_unique_cargo_vessel_user`);
+    db.exec(`
+      CREATE UNIQUE INDEX IF NOT EXISTS idx_matches_unique_cargo_vessel_user_item
+      ON matches(cargo_id, vessel_id, COALESCE(user_id, ''),
+                 COALESCE(cargo_item_index, 0), COALESCE(vessel_item_index, 0))
+    `);
+  },
+  down(db) {
+    db.exec(`DROP INDEX IF EXISTS idx_matches_unique_cargo_vessel_user_item`);
+    db.exec(`
+      CREATE UNIQUE INDEX IF NOT EXISTS idx_matches_unique_cargo_vessel_user
+      ON matches(cargo_id, vessel_id, COALESCE(user_id, ''))
+    `);
+  },
+};
+
+export default migration051;
